@extends('layouts.admin') @section('title',$order->order_code) @section('content')<div class="page-header"><div><h1 class="page-title">{{ $order->order_code }}</h1><p class="page-subtitle">{{ $order->tableSession->restaurantTable->name }} · {{ $order->created_at->format('d/m/Y H:i') }}</p></div><div class="actions"><a class="btn btn-secondary" href="{{ route('orders.index') }}">Quay lại</a><span class="badge badge-{{ $order->status->value }}">{{ $order->status->value }}</span></div></div><div class="content-grid"><section class="panel"><h2 class="section-title">Chi tiết món</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Món</th><th>SL</th><th>Đơn giá</th><th>Thành tiền</th><th>Ghi chú</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td class="cell-title">{{ $item->product_name }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->unit_price) }} đ</td><td>{{ number_format($item->subtotal) }} đ</td><td>{{ $item->note?:'—' }}</td></tr>@endforeach</tbody></table></div><div class="bill-total"><span>Tổng</span><span>{{ number_format($order->total) }} đ</span></div></section><aside class="panel"><h2 class="section-title">Cập nhật trạng thái</h2>@php($next=match($order->status->value){'pending'=>['confirmed','cancelled'],'confirmed'=>['preparing','cancelled'],'preparing'=>['ready','cancelled'],'ready'=>['served'],'served'=>['completed'],default=>[]})@forelse($next as $status)<form method="post" action="{{ route('orders.status',$order) }}" @if($status==='cancelled') data-confirm="Hủy order này? Kho đã trừ sẽ không tự động hoàn." @endif style="margin-bottom:9px">@csrf @method('patch')<input type="hidden" name="status" value="{{ $status }}">@if($status==='cancelled')<input class="form-control" name="reason" required placeholder="Lý do hủy" style="margin-bottom:8px">@endif<button class="btn {{ $status==='cancelled'?'btn-danger':'btn-primary' }} btn-block">{{ $status }}</button></form>@empty<div class="empty">Order đã ở trạng thái cuối.</div>@endforelse</aside></div>@endsection
